-- Migration: Year 4 - Ethics, Law & Health Systems (PART 6: 251-300)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — Economics, Fraud/Abuse, & Quality

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- SECTION: HEALTHCARE ECONOMICS
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which economic concept describes the tendency for people to use more healthcare services when they are insured and do not face the full cost?', '["Adverse Selection", "Moral Hazard", "Supply-Induced Demand", "Price Gouging"]', 1, 'Moral hazard occurs when insurance coverage changes an individual''s behavior, leading to higher utilization.'),
    (v_topic_id, 'What is "Adverse Selection" in the insurance market?', '["When people choose the wrong insurance", "When high-risk (sick) individuals are more likely to buy insurance than low-risk (healthy) individuals", "When a doctor refuses to see a patient", "When the government shuts down a plan"]', 1, 'Adverse selection leads to a "sick" pool of enrollees and rising premiums.'),
    (v_topic_id, 'A "Death Spiral" in an insurance pool occurs when:', '["The doctors in the plan all retire", "Premiums rise so high that healthy people leave, causing premiums to rise further for the remaining sicker members", "The hospital experiences a high mortality rate", "The insurance company loses its license"]', 1, 'Without healthy members to subsidize the sick, the plan becomes unsustainable.'),
    (v_topic_id, 'Which of the following describes "Supply-Induced Demand"?', '["Patients asking for more tests", "Clinicians ordering more tests or procedures than are medically necessary because they are paid for each service", "A shortage of doctors", "High prices for medications"]', 1, 'This is a form of moral hazard on the provider side, often linked to fee-for-service reimbursement.'),
    (v_topic_id, 'What is "Cost-Shifting"?', '["Moving a patient to a different room", "Charging private insurers higher rates to make up for low reimbursement from government payers (Medicare/Medicaid) or uncompensated care", "Paying for a bill in installments", "None of the above"]', 1, 'Cost-shifting is a common explanation for high private insurance rates.'),
    (v_topic_id, 'Which of the following is a "Global Budget" system?', '["Paying for every pill", "Providing a hospital with a fixed amount of money for the entire year to cover all services provided", "The total healthcare spending of a country", "A way to bill international patients"]', 1, 'Global budgets (common in some parts of Maryland and in Canada) encourage hospitals to focus on efficiency and prevention.'),

    -- SECTION: EMTALA (EMERGENCY MEDICAL TREATMENT AND LABOR ACT)
    (v_topic_id, 'Under EMTALA, what is the hospital''s first obligation when a patient arrives at the Emergency Department?', '["Check for insurance", "Perform a Medical Screening Examination (MSE) to determine if an Emergency Medical Condition (EMC) exists", "Ask for a deposit", "Call the patient''s primary doctor"]', 1, 'The MSE must be performed regardless of ability to pay and before asking about insurance.'),
    (v_topic_id, 'Does EMTALA apply to a patient who arrives in active labor?', '["No, only for accidents", "Yes, "stabilizing" for a pregnant woman means delivery of the child and the placenta", "Only if the baby is premature", "Only if the mother is uninsured"]', 1, 'The "Labor" part of EMTALA specifically protects pregnant patients.'),
    (v_topic_id, 'If a patient is found to have an Emergency Medical Condition (EMC), what must the hospital do before attempting a transfer?', '["Get a signature from the mayor", "Stabilize the patient to the extent of the hospital''s capability", "Check the patient''s credit", "Wait for the patient to feel better"]', 1, 'Stabilization is required before any transfer unless the risks of staying outweigh the benefits of moving to a more capable facility.'),
    (v_topic_id, 'EMTALA is often called the "Anti-Dumping" law because it prevents:', '["Dumping trash in a hospital", "Transferring uninsured or low-income patients to other facilities without stabilization (patient dumping)", "Ordering too many tests", "Hiring unqualified doctors"]', 1, 'It was enacted in 1986 to stop private hospitals from "dumping" poor patients onto public ones.'),

    -- SECTION: ANTI-FRAUD & ABUSE (STARK, ANTI-KICKBACK, FALSE CLAIMS)
    (v_topic_id, 'What does the "Stark Law" (Physician Self-Referral Law) prohibit?', '["A doctor seeing too many patients", "A physician referring a Medicare/Medicaid patient to an entity for "designated health services" if the physician has a financial relationship with that entity", "A doctor charging more than the limiting charge", "A doctor working in two different states"]', 1, 'Stark is a "strict liability" law, meaning intent does not have to be proven to find a violation.'),
    (v_topic_id, 'The "Anti-Kickback Statute" (AKS) is a criminal law that prohibits:', '["Kicking a patient", "Knowingly and willfully offering or receiving any "remuneration" to induce or reward referrals for items or services paid for by federal healthcare programs", "Billing for a service that wasn''t performed", "None of the above"]', 1, 'AKS is broader than Stark as it covers all federal programs (not just Medicare/Medicaid) and all services (not just DHS).'),
    (v_topic_id, 'Which of the following is a "Safe Harbor" in the context of the Anti-Kickback Statute?', '["A place for boats", "Specific types of business arrangements that are exempt from prosecution because they are unlikely to lead to fraud/abuse", "A hospital parking lot", "A way to hide money"]', 1, 'Safe harbors provide legal "cover" for common arrangements like space rentals or investment in large publicly traded companies.'),
    (v_topic_id, 'The "False Claims Act" (FCA) is the government''s primary tool for fighting billing fraud. What is a "Qui Tam" (Whistleblower) provision?', '["A type of medication", "A provision that allows a private individual (relator) to sue on behalf of the government and share in the recovered funds", "A requirement to bill in Latin", "None of the above"]', 1, 'Whistleblowers are a major source of FCA investigations in the healthcare industry.'),
    (v_topic_id, 'If a lab provides a doctor with free expensive meals in exchange for the doctor sending all their blood tests to that lab, which law is most likely being violated?', '["HIPAA", "ERISA", "Anti-Kickback Statute", "EMTALA"]', 2, 'The meals are "remuneration" used to induce referrals.'),

    -- SECTION: PATIENT SAFETY & QUALITY IMPROVEMENT
    (v_topic_id, 'A "Sentinel Event" is defined as:', '["A minor mistake", "A patient safety event (not primarily related to the natural course of the illness) that reaches a patient and results in death, permanent harm, or severe temporary harm", "The birth of a healthy baby", "A planned surgery"]', 1, 'Sentinel events require immediate investigation and a Root Cause Analysis.'),
    (v_topic_id, 'Which of the following is a "Never Event"?', '["A patient getting a cold", "Surgery performed on the wrong body part", "A doctor being late", "The hospital running out of coffee"]', 1, 'Never events are errors that are clearly identifiable, preventable, and serious.'),
    (v_topic_id, 'What is a "Root Cause Analysis" (RCA)?', '["Looking at a plant", "A structured method used to analyze serious adverse events to identify underlying system flaws rather than focusing on individual blame", "A way to calculate a doctor''s salary", "None of the above"]', 1, 'RCAs focus on the "why" of a system failure to prevent future occurrences.'),
    (v_topic_id, 'The "Swiss Cheese Model" of system failure suggests that:', '["Errors only happen in Switzerland", "Accidents happen when multiple small failures (holes in the cheese) align, allowing a hazard to reach a patient", "Hospitals should serve more cheese", "None of the above"]', 1, 'It emphasizes that safety is about building multiple layers of defense (barriers).'),
    (v_topic_id, 'What is the "PDSA" cycle in quality improvement?', '["Patient Doctor Safety Association", "Plan-Do-Study-Act: A four-step model for carrying out change", "Please Do Something Always", "None of the above"]', 1, 'PDSA is a fundamental tool for iterative process improvement.'),
    (v_topic_id, 'A "Culture of Safety" in a hospital is one where:', '["Staff are fired for any mistake", "Staff feel comfortable reporting errors and near-misses without fear of retribution, and the focus is on learning and improvement", "Patients are kept in locked rooms", "None of the above"]', 1, 'Psychological safety is critical for a high-reliability organization.'),

    -- SECTION: PAYER SYSTEMS & ACOs
    (v_topic_id, 'What is an "Accountable Care Organization" (ACO)?', '["A group of lawyers", "A group of doctors and hospitals that collaborate to provide high-quality, coordinated care to their Medicare patients and share in any savings achieved", "A government agency that audits taxes", "None of the above"]', 1, 'ACOs are a key part of the move toward "value-based" care.'),
    (v_topic_id, 'In an ACO, if the group reduces costs while maintaining quality, they may receive:', '["A fine", "Shared Savings payments from Medicare", "More patients", "Free medical equipment"]', 1, 'This "upside risk" incentivizes efficient, high-quality care.'),
    (v_topic_id, 'Which of the following describes "Prospective Payment" (e.g., using DRGs)?', '["Paying for services after they happen", "Paying a fixed amount for a specific diagnosis or procedure BEFORE the services are provided, regardless of the actual cost", "Paying for care with a credit card", "None of the above"]', 1, 'Diagnosis-Related Groups (DRGs) are used by Medicare to pay hospitals a set fee for a "hip replacement" or "pneumonia stay."'),

    -- SECTION: QUALITY METRICS
    (v_topic_id, 'What are "HEDIS" (Healthcare Effectiveness Data and Information Set) scores used for?', '["Measuring the height of patients", "Comparing the performance of health plans on important dimensions of care and service", "Calculating the price of drugs", "None of the above"]', 1, 'HEDIS is the most widely used set of performance measures in the managed care industry.'),
    (v_topic_id, 'What is the "CAHPS" (Consumer Assessment of Healthcare Providers and Systems) survey?', '["A survey of doctor''s salaries", "A standardized survey used to measure patient experience and satisfaction with their care", "A test for nurses", "None of the above"]', 1, 'Patient experience is a core component of "quality" in modern healthcare.'),
    (v_topic_id, 'The "Joint Commission" (TJC) is primarily responsible for:', '["Writing medical textbooks", "Accrediting and certifying healthcare organizations in the US based on safety and quality standards", "Paying Medicare claims", "Arresting doctors for fraud"]', 1, 'TJC accreditation is essential for most hospitals to receive reimbursement.'),

    -- SECTION: DISPARITIES & SOCIAL DETERMINANTS
    (v_topic_id, 'What are "Social Determinants of Health" (SDoH)?', '["The genes you are born with", "The conditions in which people are born, grow, live, work, and age (e.g., housing, education, food security) that impact health outcomes", "The number of friends a patient has", "None of the above"]', 1, 'SDoH are estimated to account for up to 80% of health outcomes.'),
    (v_topic_id, 'Which of the following is an example of a "Health Disparity"?', '["A tall person having a higher risk of back pain", "A higher rate of diabetes among low-income minority populations compared to higher-income groups", "Two people having different eye colors", "None of the above"]', 1, 'Disparities are differences in health outcomes that are closely linked with social, economic, or environmental disadvantage.'),
    (v_topic_id, 'What is "Implicit Bias" in a healthcare setting?', '["When a doctor openly hates a patient", "Unconscious associations or stereotypes that affect a provider''s understanding, actions, and decisions regarding a patient", "A type of surgical error", "None of the above"]', 1, 'Implicit bias can lead to inequitable treatment even among well-meaning clinicians.'),

    -- SECTION: MISCELLANEOUS HEALTH SYSTEMS
    (v_topic_id, 'Which of the following describes "Telehealth"?', '["Watching TV in the hospital", "The use of electronic information and telecommunications technologies to support long-distance clinical health care and education", "Calling a pharmacy", "None of the above"]', 1, 'Telehealth expanded massively during the COVID-19 pandemic and is now a permanent part of the system.'),
    (v_topic_id, 'What is a "Patient-Centered Medical Home" (PCMH)?', '["A nursing home", "A model of primary care that is patient-centered, comprehensive, team-based, coordinated, accessible, and focused on quality and safety", "A hospital where the patient''s family stays with them", "None of the above"]', 1, 'The PCMH is designed to strengthen the physician-patient relationship.'),
    (v_topic_id, 'What is "Concierge Medicine"?', '["A doctor who works in a hotel", "A model where patients pay an out-of-pocket retainer fee for enhanced access and more personalized care from their physician", "A free clinic", "None of the above"]', 1, 'Concierge medicine often limits the physician''s panel size to provide more time per patient.'),
    (v_topic_id, 'What is "Medical Tourism"?', '["Traveling to a different city for a specialized surgery", "Traveling to another country to receive medical treatment, often to save money or access services not available at home", "Doctors traveling to conferences", "None of the above"]', 1, 'Medical tourism is a multi-billion dollar global industry.'),
    (v_topic_id, 'The "National Health Service" (NHS) model (e.g., in the UK) is an example of:', '["Single-payer socialized medicine where the government owns the hospitals and employs the staff", "Private insurance only", "A system like the US", "None of the above"]', 0, 'In the US, the VA (Veterans Affairs) is the closest equivalent to a true socialized medicine system.'),
    (v_topic_id, 'The "Bismarck Model" (e.g., in Germany) is characterized by:', '["Government-run hospitals", "Private insurance plans (Sickness Funds) that are non-profit and tightly regulated, often funded by employers and employees", "No insurance at all", "None of the above"]', 1, 'The Bismarck model uses private providers but universal, non-profit insurance.'),
    (v_topic_id, 'Which of the following is true regarding "Price Transparency" rules in the US?', '["Hospitals are allowed to hide their prices", "Hospitals are required by federal law to post their "standard charges" for all items and services online in a machine-readable format", "Prices are the same everywhere", "None of the above"]', 1, 'CMS price transparency rules aim to empower consumers to "shop" for care.'),
    (v_topic_id, 'What is "Physician Burnout"?', '["A doctor who gets too hot", "A long-term stress reaction marked by emotional exhaustion, depersonalization, and a lack of sense of personal accomplishment", "When a doctor retires", "None of the above"]', 1, 'Burnout is a systemic problem linked to administrative burden and poor work environments.'),
    (v_topic_id, 'What is "Defensive Medicine"?', '["A doctor learning karate", "The practice of ordering tests or treatments primarily to protect the clinician from potential malpractice lawsuits, rather than for the patient''s benefit", "Locked hospital wards", "None of the above"]', 1, 'Defensive medicine adds significant cost to the healthcare system without necessarily improving outcomes.'),
    (v_topic_id, 'What is the "Standard of Care"?', '["The absolute best possible treatment", "The level at which the average, prudent provider in a given community would practice", "A list of rules from the government", "None of the above"]', 1, 'Medical malpractice is defined as a deviation from the standard of care that causes harm.'),
    (v_topic_id, 'The "EMTALA" medical screening exam must be performed by:', '["A receptionist", "A "Qualified Medical Person" (QMP), such as a physician, PA, or ARNP as designated by the hospital bylaws", "A security guard", "None of the above"]', 1, 'Triage by a nurse is NOT an MSE under EMTALA.'),
    (v_topic_id, 'If a hospital has "specialized capabilities" (e.g., a burn unit or NICU), are they required to accept a transfer under EMTALA?', '["No", "Yes, if they have the capacity to treat the patient", "Only if the patient is rich", "Only on weekdays"]', 1, 'Hospitals with specialized units have a "nondiscrimination" duty to accept transfers from hospitals without those capabilities.'),
    (v_topic_id, 'What is a "Benchmark" in healthcare quality?', '["A seat in a park", "A standard or point of reference against which things may be compared or assessed", "A type of surgery", "None of the above"]', 1, 'Benchmarking allows organizations to see how they perform compared to their peers.'),
    (v_topic_id, 'What is "Total Quality Management" (TQM)?', '["Checking only the final product", "An organization-wide approach to continuously improving the quality of all processes and services", "Firing poor-performing employees", "None of the above"]', 1, 'TQM emphasizes that quality is everyone''s responsibility.'),
    (v_topic_id, 'The "Iron Triangle" of healthcare refers to the trade-offs between:', '["Doctors, Nurses, and Patients", "Cost, Quality, and Access", "Hospitals, Insurers, and Pharma", "None of the above"]', 1, 'It is difficult to improve one of these without negatively impacting the others.'),
    (v_topic_id, 'What is "Health Literacy"?', '["Being able to read a medical textbook", "The degree to which individuals have the capacity to obtain, process, and understand basic health information and services needed to make appropriate health decisions", "Knowing the names of all the bones", "None of the above"]', 1, 'Low health literacy is a major driver of poor health outcomes.'),
    (v_topic_id, 'Which of the following is a "Structural" measure of quality?', '["The percentage of patients who get a flu shot", "The ratio of nurses to patients on a unit", "The number of patients who die after surgery", "None of the above"]', 1, 'Structural measures look at the capacity and environment of care.'),
    (v_topic_id, 'Which of the following is a "Process" measure of quality?', '["The presence of an EHR system", "The percentage of diabetic patients who received an annual foot exam", "The hospital readmission rate", "None of the above"]', 1, 'Process measures look at what is actually done to the patient.'),
    (v_topic_id, 'Which of the following is an "Outcome" measure of quality?', '["The number of board-certified doctors", "The mortality rate for heart failure patients", "The use of a checklist before surgery", "None of the above"]', 1, 'Outcome measures look at the results of the care provided.'),
    (v_topic_id, 'In "Value-Based Care," "Value" is typically defined as:', '["The total cost of the procedure", "Quality (Outcomes + Experience) divided by Cost", "The number of patients seen", "The profit of the hospital"]', 1, 'The goal is to maximize quality for every dollar spent.')
;

END $$;
COMMIT;
